#!/usr/bin/env python3
import base64, os

os.makedirs(os.path.dirname("frontend/src/app/games/live/[token]/page.tsx"), exist_ok=True)
open("frontend/src/app/games/live/[token]/page.tsx", "wb").write(base64.b64decode(""))
print("wrote frontend/src/app/games/live/[token]/page.tsx")
os.makedirs(os.path.dirname("frontend/src/app/games/[id]/page.tsx"), exist_ok=True)
open("frontend/src/app/games/[id]/page.tsx", "wb").write(base64.b64decode(""))
print("wrote frontend/src/app/games/[id]/page.tsx")

import subprocess
subprocess.run(["git","update-index","--add","frontend/src/app/games/[id]/page.tsx"])
subprocess.run(["git","update-index","--add","frontend/src/app/games/live/[token]/page.tsx"])
r = subprocess.run(["git","commit","-m","Fix live table display, notifications, watch live button"], capture_output=True, text=True)
print(r.stdout, r.stderr)
subprocess.run(["git","push"])